import { redirect } from "next/navigation"
import { AlertTriangle, ServerCrash } from "lucide-react"

import { AccessDeniedScreen } from "@/components/app-shell/access-denied-screen"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { getServerApiOrigin, getServerApiPort } from "@/lib/server/api-origin"
import { getRootRouteState } from "@/lib/utils/route-guards"

export const dynamic = "force-dynamic"

export default async function Home() {
  const apiPort = getServerApiPort()
  const apiHealthUrl = `${getServerApiOrigin()}/api/health`
  const state = await getRootRouteState()

  if (state.kind === "setup-required") {
    redirect("/setup")
  }

  if (state.kind === "unauthenticated") {
    redirect("/login")
  }

  if (state.kind === "authenticated") {
    redirect("/dashboard")
  }

  if (state.kind === "ip-forbidden") {
    return (
      <AccessDeniedScreen
        theme="dark"
        contextLabel="Status"
        message={state.message}
        instanceName={state.instance.instanceName}
      />
    )
  }

  return (
    <main className="flex min-h-svh items-center justify-center px-6 py-16">
      <Card className="w-full max-w-xl border-white/10 bg-black/40 shadow-[0_0_50px_rgba(255,75,51,0.06)] backdrop-blur-sm">
        <CardHeader>
          <div className="mb-2 flex size-12 items-center justify-center rounded-2xl bg-[#FF4B33]/12 text-[#FF8F66]">
            <ServerCrash className="size-6" />
          </div>
          <CardTitle className="text-2xl text-white">Arciin is waiting on its instance service.</CardTitle>
          <CardDescription className="text-sm text-zinc-400">
            The web shell loaded, but the instance service is not ready yet. Check the API on
            port <span className="mx-1 font-mono text-zinc-300">{apiPort}</span>, Redis, and your
            database credentials, or update{" "}
            <span className="font-mono text-zinc-300">ARCIIN_API_URL</span>.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-start gap-3 rounded-xl border border-white/8 bg-white/[0.03] p-4 text-sm text-zinc-300">
            <AlertTriangle className="mt-0.5 size-4 shrink-0 text-[#F59E0B]" />
            <p>
              This route will automatically redirect to <span className="font-mono">/setup</span>,
              <span className="mx-1 font-mono">/login</span>, or
              <span className="ml-1 font-mono">/dashboard</span> once the API and database are ready.
            </p>
          </div>
          <Button asChild size="lg" className="w-full bg-primary text-white hover:bg-primary/90">
            <a href={apiHealthUrl} target="_blank" rel="noreferrer">
              Probe API health
            </a>
          </Button>
        </CardContent>
      </Card>
    </main>
  )
}
